namespace Atc.Rest.Api.Generator.Tests.Models;

public class GeneratedEnumDeclarationTests
{
    [Fact]
    public void FindIn_AStringAndAnIntegerEnum_NamesEachFullyQualified_WithItsWireForm()
    {
        const string content = """
            // <auto-generated />
            namespace Contoso.Generated.Models;

            [GeneratedCode("Atc.Rest.Api.SourceGenerator", "1.0.0")]
            [JsonConverter(typeof(JsonStringEnumConverter<Color>))]
            public enum Color
            {
                Red,
            }

            [JsonConverter(typeof(JsonNumberEnumConverter<Level>))]
            public enum Level : long
            {
                Low = 1,
            }
            """;

        var enums = GeneratedEnumDeclaration.FindIn(content);

        Assert.Equal(
            [
                new GeneratedEnumDeclaration("global::Contoso.Generated.Models.Color", IsInteger: false),
                new GeneratedEnumDeclaration("global::Contoso.Generated.Models.Level", IsInteger: true),
            ],
            enums);
    }

    [Theory]
    [InlineData("namespace Contoso.Generated.Models;\n\npublic sealed record Pet(string Name);\n")]
    [InlineData("namespace Contoso.Generated.Models;\n\n/// <summary>An enum of colors.</summary>\npublic readonly partial struct Color;\n")]
    [InlineData("")]
    public void FindIn_AFileWithoutAnEnum_FindsNone(string content)
        => Assert.Empty(GeneratedEnumDeclaration.FindIn(content));
}